// The Worker's secrets and where each value comes from.

import { randomBytes } from 'node:crypto';

export type SecretSource =
  /** Generated by the setup on the first run. */
  | 'generated'
  /** Created by the setup with the Realtime SFU app or TURN key (the token is shown only once). */
  | 'realtime'
  /** Read from `wrangler whoami`. */
  | 'account'
  /** Filled in by the person who deploys (docs/self-host.md). */
  | 'user'
  /** Optional: the feature it enables stays off until it is filled in. */
  | 'optional';

export interface SecretSpec {
  name: string;
  source: SecretSource;
  description: string;
}

export const SECRETS: readonly SecretSpec[] = [
  { name: 'SESSION_SECRET', source: 'generated', description: 'signs session cookies' },
  {
    name: 'INSTALL_CODE',
    source: 'generated',
    description: 'claims the first admin account',
  },
  { name: 'REALTIME_APP_ID', source: 'realtime', description: 'Realtime SFU app id' },
  { name: 'REALTIME_APP_TOKEN', source: 'realtime', description: 'Realtime SFU app secret' },
  { name: 'TURN_KEY_ID', source: 'realtime', description: 'Realtime TURN key id' },
  { name: 'TURN_KEY_TOKEN', source: 'realtime', description: 'Realtime TURN key secret' },
  { name: 'CLOUDFLARE_ACCOUNT_ID', source: 'account', description: 'for the usage cron' },
  { name: 'DISCORD_CLIENT_ID', source: 'user', description: 'Discord OAuth app' },
  { name: 'DISCORD_CLIENT_SECRET', source: 'user', description: 'Discord OAuth app' },
  { name: 'RESEND_API_KEY', source: 'user', description: 'magic-link e-mail (send-only key)' },
  {
    name: 'CLOUDFLARE_API_TOKEN',
    source: 'optional',
    description: 'real egress in the usage cron (token with Account Analytics: Read)',
  },
  {
    name: 'HELPER_UPDATE_SIGNING_PUBKEY',
    source: 'optional',
    description: 'helper update checks (a later phase)',
  },
];

/** Names that must never reach a deployed environment (src/room/identity.ts). */
export const FORBIDDEN_IN_DEPLOY: readonly string[] = ['DEV_AUTH'];

/** 32 random bytes, base64url. */
export function generateSessionSecret(random: (n: number) => Buffer = randomBytes): string {
  return random(32).toString('base64url');
}

// Crockford base32 without the letters people confuse (I, L, O, U).
const CODE_ALPHABET = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';

/** A code people can type from the terminal: 3 groups of 4 (60 bits), e.g. `7K2Q-M9XD-4RTB`. */
export function generateInstallCode(random: (n: number) => Buffer = randomBytes): string {
  const bytes = random(12);
  const chars = [...bytes].map((b) => CODE_ALPHABET[b % 32]).join('');
  return `${chars.slice(0, 4)}-${chars.slice(4, 8)}-${chars.slice(8, 12)}`;
}
